function UIActivityMainBambooNode:ReConventTime(dojo)
    local result = ActivityDojo.New()
    result:Fill(dojo)
    --时间还原   活动在接收数据时使用ConventSecondToTimeStamp转换了时间
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not comp then
        return
    end
    local curTime = comp:GetPlayerDojo():GetServerTime()
    curTime = curTime or os.time()
    result.startTime = checkNumber(result.startTime) - curTime
    result.endTime = checkNumber(result.endTime) - curTime
    result.closeTime = checkNumber(result.closeTime) - curTime
    return result
end

function UIActivityMainBambooNode:FillSelf()
    local curTime = os.time()
    local startTime = curTime + self._data.startTime
    local closeTime = curTime + self._data.closeTime
    --CfUtils.FillText(self.Text, os.date("%Y.%m.%d", startTime).." 5:00:00 ~ "..os.date("%Y.%m.%d", closeTime).." 4:59:59")
    ---@type ActivityUtils
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.Text, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.EndTimeText, CfUtils.GetTimeHMS3(self._data.closeTime))

    self:HandleStateTimeDown()
end

function UIActivityMainBambooNode:HandleStateTimeDown()
    self:ClearTimeDown()
    self._tiemDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._data.closeTime = self._data.closeTime - 1
        CfUtils.FillText(self.EndTimeText, CfUtils.GetTimeHMS3(self._data.closeTime))
    end, 2592000, false, true)
end

function UIActivityMainBambooNode:ClearTimeDown()
    if not isNull(self._tiemDown) then
        CDTimerModule.GetInstance():RemoveCD(self._tiemDown)
        self._tiemDown = nil
    end
end

function UIActivityMainBambooNode:OnClick()
    print(table.dump(BambooQuestComponent:GetBambooActivityDojo(self._data.id)))
    if BambooQuestComponent:IsActivityStart(self._data.id) then
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        BambooQuestComponent:ActivityQuestHomeReq(self._data.id, function()
            local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')

            local vo = BambooUtils.GetBambooActivityVo(BambooUtils.GetActivityId(self._data.id))
            if not vo then
                return
            end

            local isUnlock = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum, vo.unlockId)
            if not isUnlock then
                local err = GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum, vo.unlockId)
                GameUtils.Toast(err)
                return
            end
            KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, BambooQuestComponent:GetCuractivityUuid())
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIBambooMainDialog, parameters = {activityUuid = BambooQuestComponent:GetCuractivityUuid()}}, { { id = Constants.UITypeIds.UIActivityMainDialog } })
        end)
    else
        GameUtils.Toast(localize("活动未开始"))
    end
end

function UIActivityMainBambooNode:OnBtnTips()
    GameUtils.ShowCommonTipsBoard(self.BtnTips, localize("活动详情"), self._data.detail)
end

function UIActivityMainBambooNode:OnDestroy()
    self:ClearTimeDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityMainBambooNode
